ABSENT = [
    "Which sourdough hydration produces the lightest crust in a wood-fired oven?",
    "How should a violin bow contact point change for a soft harmonic?",
    "Which ocean current carries larval coral across the Pacific?",
    "What lunar gravity assist minimizes a spacecraft's propellant use?",
    "How does a patient's blood oxygen affect anesthetic dosing?",
    "Which tax deduction applies to my personal house purchase?",
    "How can an acoustic piano's hammer felt be voiced more softly?",
    "What geological process created the mineral bands in an agate?",
]

def write(path, value):
    path.write_bytes((json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False)+"\n").encode())

def build():
    assert len(FRESH)==24
    paths=[ROOT/'data/corpus-v2.json', ROOT/'data/queries-v2.json', ROOT/'frozen-v2.json']
    if any(path.exists() for path in paths):
        raise RuntimeError('v2 authoring is already frozen; use another version, never overwrite.')
    old=json.loads((ROOT/'data/corpus-v1.json').read_bytes())
    old_queries=json.loads((ROOT/'data/queries-v1.json').read_bytes())['queries']
    development={q['group'] for q in old_queries if q['split']=='development'}
    docs=[d for d in old['documents'] if d['group'] in development]
    queries=[q for q in old_queries if q['split']=='development']
    ordered=sorted((row[0] for row in FRESH), key=lambda key:hashlib.sha256((VERSION+key).encode()).hexdigest())
    splits={key:'calibration' if i<12 else 'test' for i,key in enumerate(ordered)}
    for i,(key,title,body,title_b,body_b,literal,paraphrase,challenge) in enumerate(FRESH):
        a,b=f'discussion-v2-{i+1:03d}-a',f'discussion-v2-{i+1:03d}-b'
        docs.extend([{'id':a,'group':key,'title':title,'text':body,'category':'Engineering discussion'}, {'id':b,'group':key,'title':title_b,'text':body_b,'category':'Engineering discussion'}])
        for kind,text,relevance in [('literal',literal,{a:2,b:1}),('paraphrase',paraphrase,{a:2,b:1}),('no_answer' if i%3==0 else 'distractor',ABSENT[i//3] if i%3==0 else challenge,{} if i%3==0 else {b:2,a:1})]:
            queries.append({'id':f'{key}-{kind}','group':key,'split':splits[key],'slice':kind,'text':text,'relevance':relevance})
    # These public links exist independently of query judgements.
    for doc in docs:
        doc['related_ids']=[other['id'] for other in docs if other['group']==doc['group'] and other['id']!=doc['id']]
    provenance={**old['provenance'],'version':VERSION,'split_policy':'v1 development retained; 24 newly authored families hash-ordered into 12 calibration and 12 test groups before encoding. No v1 calibration/test query reused.', 'limitations':'AI-authored English fixture, public paired-thread links and sparse pair judgements can favor relation expansion. No independent human review or production guarantee.'}
    write(paths[0],{'provenance':provenance,'documents':docs}); write(paths[1],{'provenance':provenance,'queries':queries})
    frozen={'version':VERSION,'groups':{'development':sorted(development), **{split:sorted(key for key,value in splits.items() if value==split) for split in ('calibration','test')}},'sha256':{path.name:hashlib.sha256(path.read_bytes()).hexdigest() for path in paths[:2]},'policy':{'retriever':'cosine-related-v2','expand':'Explicit related_ids after each leading unvisited discussion, capped at five, stable cosine/ID order. No query labels at runtime.','confidence_features':['top cosine','margin to next unrelated group'],'minimum_recall_at_5':.85,'require_paraphrase_improvement_over_bm25':True},'development_selection':'v1 development: plain cosine .782609, public sibling expansion .951087; lexical RRF did not improve over expansion.'}
    write(paths[2],frozen)
    print(f'Frozen v2: {len(docs)} documents, {len(queries)} queries; fresh 12 calibration and 12 test families.',flush=True)

if __name__=='__main__': build()
